bounded_host_request.command:
set -euo pipefail
gay="$(docker ps --format '{{.Names}}' | grep -Ei '(^|[-_])gaybbs([-_]|$)' || true)"
test "$(printf '%s\n' "$gay" | sed '/^$/d' | wc -l)" -eq 1 || { echo STK04_GROUP_CONTAINER_AMBIGUOUS; exit 61; }
state_dir="$HOME/.local/state/gace-stk04"
mkdir -p "$state_dir";chmod 700 "$state_dir"
receipt="$state_dir/creator_dm_2373696859.pin"
exec 9>"$state_dir/creator_dm_2373696859.lock"
flock -n 9 || { echo STK04_OTHER_PIN_OPERATION_ACTIVE; exit 62; }
status="$(cat "$receipt" 2>/dev/null || true)"
if [ "$status" = "PINNED" ]; then echo STK04_PRIOR_PIN_ACK_PRESERVED;exit 0; fi
case "$status" in
 POSTED:*) mid="${status#POSTED:}";;
 "") 
  echo SENDING > "$receipt"
  tmp="$(mktemp /tmp/gace-stk04-send.XXXXXXXX)"
  trap 'rm -f "$tmp"' EXIT
  if docker exec -i "$gay" node --input-type=module - >"$tmp" 2>&1 <<'STK04_SEND_NODE'
import fs from "node:fs";import https from "node:https";
const file=process.env.BOT_TOKEN_FILE;
if(!file||!file.startsWith("/")){console.log("STK04_TOKEN_CONFIG_MISSING");process.exit(1)}
const secret=fs.readFileSync(file,"utf8").trim();
if(!/^[0-9]{7,15}:[A-Za-z0-9_-]{30,100}$/.test(secret)){console.log("STK04_GROUP_TOKEN_INVALID");process.exit(1)}
const invoke=(method,body)=>new Promise((resolve,reject)=>{
const data=JSON.stringify(body);const req=https.request({
hostname:"api.telegram.org",port:443,family:4,path:"/bot"+secret+"/"+method,method:"POST",
headers:{"Content-Type":"application/json","Content-Length":Buffer.byteLength(data)},timeout:12000
},resp=>{let s="";resp.on("data",c=>{if(s.length<65536)s+=c});resp.on("end",()=>{
try{const j=JSON.parse(s);if(j.ok===true)resolve(j.result);else reject(Error("API_"+method+"_REJECTED_"+String(j.error_code??0)))}catch(e){reject(e)}
});});
req.on("timeout",()=>req.destroy(Error("TIMEOUT")));req.on("error",e=>reject(Error("CONNECT_"+String(e.code??"UNKNOWN"))));req.end(data);
});
try{
const me=await invoke("getMe",{});if(me.is_bot!==true||me.username?.toLowerCase()!=="gaybbs_bot")throw Error("GROUP_IDENTITY_INVALID");
const chat=await invoke("getChat",{chat_id:-1002373696859});
if(chat.is_forum!==true||chat.type!=="supergroup"||Number(chat.id)!==-1002373696859)throw Error("FORUM_ID_INVALID");
const member=await invoke("getChatMember",{chat_id:-1002373696859,user_id:me.id});
if(!["administrator","creator"].includes(member.status)||(member.status==="administrator"&&member.can_pin_messages!==true))throw Error("PIN_AUTH_MISSING");
console.log("STK04_PRE_SEND_AUTH=PASS");
const sent=await invoke("sendMessage",{
 chat_id:-1002373696859,message_thread_id:4291,
 reply_parameters:{message_id:4640,allow_sending_without_reply:false},
 text:"🎨 ステッカー作成・投稿はこちら\n下のボタンからCreateVdobotのDMを開いてください。",
 reply_markup:{inline_keyboard:[[{text:"🎨 投稿はこちら",url:"https://t.me/CreateVdobot?start=sticker"}]]},
 disable_notification:true
});
if(!Number.isSafeInteger(sent?.message_id)||sent.message_id<=0)throw Error("SEND_ID_UNKNOWN");
console.log("STK04_SENT_MESSAGE_ID="+sent.message_id);
if(sent.is_topic_message!==true||sent.message_thread_id!==4291||
 (sent.reply_to_message?.message_id!==undefined&&sent.reply_to_message.message_id!==4640))throw Error("SEND_TOPIC_UNVERIFIED");
console.log("STK04_SEND_TOPIC=VERIFIED_4291");
}catch(e){console.error("STK04_SEND_ERROR="+String(e.message||"UNKNOWN").replace(/[^A-Za-z0-9_]/g,"_"));process.exitCode=1}

STK04_SEND_NODE
  then :;else
    grep -E '^STK04_(PRE_SEND_AUTH|SEND_ERROR|SENT_MESSAGE_ID|SEND_TOPIC)=' "$tmp" || true
    echo NEEDS_RECONCILE > "$receipt"
    echo STK04_SEND_NOT_VERIFIED_NO_RETRY
    exit 63
  fi
  grep -E '^STK04_(PRE_SEND_AUTH|SENT_MESSAGE_ID|SEND_TOPIC)=' "$tmp" || true
  mid="$(sed -n 's/^STK04_SENT_MESSAGE_ID=\([0-9]\+\)$/\1/p' "$tmp" | tail -n 1)"
  if [ -z "$mid" ] || ! grep -qx 'STK04_SEND_TOPIC=VERIFIED_4291' "$tmp"; then
    echo NEEDS_RECONCILE > "$receipt";echo STK04_SEND_RECEIPT_UNVERIFIED;exit 64
  fi
  echo "POSTED:$mid" > "$receipt";;
 *) echo "STK04_EXISTING_RECEIPT=$status";exit 65;;
esac
pinout="$(mktemp /tmp/gace-stk04-pin.XXXXXXXX)"
trap 'rm -f "$pinout";rm -f "${tmp:-/nonexistent}"' EXIT
if docker exec -i --env "STK04_MESSAGE_ID=$mid" "$gay" node --input-type=module - >"$pinout" 2>&1 <<'STK04_PIN_NODE'
import fs from "node:fs";import https from "node:https";
const tok=fs.readFileSync(process.env.BOT_TOKEN_FILE,"utf8").trim();
const id=Number(process.env.STK04_MESSAGE_ID);
if(!Number.isSafeInteger(id)||id<=0)throw Error("BAD_STK04_MESSAGE_ID");
const data=JSON.stringify({chat_id:-1002373696859,message_id:id,disable_notification:true});
const j=await new Promise((resolve,reject)=>{
const req=https.request({hostname:"api.telegram.org",port:443,family:4,path:"/bot"+tok+"/pinChatMessage",
method:"POST",headers:{"Content-Type":"application/json","Content-Length":Buffer.byteLength(data)},timeout:12000},
resp=>{let x="";resp.on("data",c=>{if(x.length<16384)x+=c});resp.on("end",()=>{try{resolve(JSON.parse(x))}catch(e){reject(e)}})});
req.on("timeout",()=>req.destroy(Error("PIN_TIMEOUT")));req.on("error",e=>reject(e));req.end(data);
});
if(j.ok!==true||j.result!==true){console.log("STK04_PIN_API_REJECTED_"+String(j.error_code??0));process.exitCode=1}
else console.log("STK04_TELEGRAM_PIN_ACK=PASS");

STK04_PIN_NODE
then
 if grep -qx 'STK04_TELEGRAM_PIN_ACK=PASS' "$pinout";then
   echo PINNED > "$receipt";echo "STK04_POST_MESSAGE_ID=$mid";echo STK04_TELEGRAM_PIN_ACK=PASS
 else echo "STK04_PIN_RECEIPT_NOT_VERIFIED";exit 66;fi
else
 grep -E '^STK04_PIN_API_REJECTED' "$pinout" || true
 echo STK04_PIN_RESULT_UNKNOWN_POST_PRESERVED;exit 67
fi
